solution:
pub interface Printable {
  fn format(self: &Self) -> Str;
}

pub type Book = {
  title: Str;
  pages: Int;
}

impl Printable for Book {
  fn format(self: &Book) -> Str {
    return self.title + " (" + self.pages.to_str() + " pages)";
  }
}

fn main() -> Int {
  let b = Book{ title: "XIOM Guide", pages: 300 };
  let s = b.format();
  return b.pages;
}
